                    pr(1308, ['pr_approved']),                       // merge window
                    pr(1309, ['validation_failed']),                 // parked
                    pr(1310, ['chore:pin']),                         // factory pin
                    pr(1311, [], 'CLEAN'),                           // green+CLEAN — merge-validated shape
                    pr(1312, [], 'BEHIND'),                          // silent-update refreshes first
